    {
        "name": "Hepatocellular Carcinoma",
        "name_ja": "肝細胞癌",
        "symptoms": {"anorexia", "lethargy", "liver_enlargement", "weight_loss"},
        "description": "Hepatocellular Carcinoma is a neoplastic condition characterized by abnormal cell proliferation that may be benign or malignant.",
        "description_ja": "原発性悪性肝腫瘍。",
        "urgency": "high",
        "recommended_tests": ["ultrasound", "biopsy", "blood_chemistry", "histopathology"],
        "causes": "Primary malignant hepatic neoplasia arising from hepatocyte transformation. Chronic hepatitis, toxin exposure, and aging are potential contributing factors in reptilian hepatocellular carcinoma.",
        "causes_ja": "ヘビにおける肝細胞癌の原因: 癌遺伝子・腫瘍抑制遺伝子の遺伝子変異蓄積による腫瘍性形質転換。加齢、慢性炎症、ウイルス感染、ホルモン影響、UV曝露、遺伝的素因がリスク因子。",
        "pathophysiology": "Accumulated genetic mutations lead to uncontrolled cell proliferation, evasion of apoptosis, and potential metastatic spread. Tumor growth causes tissue compression, invasion, and paraneoplastic effects.",
        "pathophysiology_ja": "肝細胞癌はヘビにおける腫瘍性疾患である。癌遺伝子、腫瘍抑制遺伝子、DNA修復機構における遺伝子変異の蓄積により腫瘍性形質転換が生じる。制御不能な細胞増殖により腫瘍が形成され、局所組織への浸潤・破壊の可能性がある。悪性腫瘍はリンパ行性または血行性に転移しうる。高カルシウム血症、悪液質、免疫調節障害などの腫瘍随伴症候群が原発腫瘍に伴い、罹患率に寄与することがある。",
        "treatment": "Hepatic lobectomy if tumor confined to 1-2 lobes; coelomic surgery requires air sac anatomy awareness. Isoflurane/sevoflurane anesthesia (slow recovery expected). Stage with radiographs and ultrasound. Chemotherapy data very limited in snakes. Hepatoprotective care (fluid therapy, assist-feeding). Meloxicam 0.1-0.2 mg/kg IM/PO q24-48h for pain.",
        "treatment_ja": "腫瘍が1-2葉に限局している場合は肝葉切除術。体腔内手術では気嚢解剖の理解が必要。イソフルラン/セボフルラン麻酔（覚醒遅延に注意）。X線撮影・超音波でステージング。ヘビでの化学療法データは極めて限定的。肝保護療法（輸液、強制給餌）。疼痛管理にメロキシカム0.1-0.2 mg/kg IM/PO q24-48h。",
        "prevention": "Prevention is limited for most neoplastic conditions. Regular health examinations facilitate early detection. Spaying/neutering may reduce risk of hormone-dependent tumors.",
        "prevention_ja": "肝細胞癌の予防は限定的であるが、ホルモン依存性腫瘍軽減のための避妊・去勢手術、既知の発癌物質の回避、早期発見のための定期健診、適正体型の維持、該当する場合は遺伝的素因軽減のための責任ある繁殖が含まれる。",
        "prognosis": "Prognosis depends on tumor type, staging, and response to treatment. Complete surgical excision of localized tumors improves outcomes. Metastatic disease carries a guarded to poor prognosis.",
        "prognosis_ja": "肝細胞癌の予後: 腫瘍の種類と病期による。早期発見で改善。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"adult", "senior"},
    },
